import {createBuildProgress,updateBuildProgress,progressRecord,progressKey,buildIdentity,highlightCheckpoint} from './guided-build.mjs';
export function mountGuidedBuild({root,mount,storage,onStart,assembly=null}){
 const doc=root.ownerDocument,node=(tag,text)=>{const n=doc.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
 let circuit,guide,state,checklist=false,storageOK=true;
 const save=()=>{try{storage.setItem(progressKey(state.identity),JSON.stringify(progressRecord(state)));}catch{storageOK=false;}};
 const button=(text,action)=>{const b=node('button',text);b.type='button';b.addEventListener('click',action);return b;};
 const act=(action,id)=>{updateBuildProgress(state,action,id);save();render(true);};
 function render(focus=false){
  root.replaceChildren();root.className='guided-build';root.dataset.buildPhase=!state.route?'entry':state.finished?'complete':state.current==='@final'?'inspection':'active';
  const progress=node('output',state.completed.length+' / '+(guide.connections.length-(state.route==='kit'?state.factoryComplete.length:0))+' connections checked'+(state.skipped.length?' · '+state.skipped.length+' skipped':''));progress.id='build-progress';progress.setAttribute('aria-live','polite');root.append(progress);
  const factory=state.route==='kit'?state.factoryComplete:[],required=guide.connections.filter(r=>!factory.includes(r.id));
  const currentStage=state.stages.find(s=>s.id===state.checkpoints.find(c=>c.id===state.current).stage),row=guide.connections.find(r=>r.id===state.current);
  const title=node('h3');title.tabIndex=-1;title.id='guided-checkpoint-title';
  if(!state.route){title.textContent='Ready to build?';root.append(title,node('p','Follow this circuit one checkpoint at a time. Each connection highlights its physical destinations on the same diagram.'),node('p',circuit.state.guitar.replaceAll('-',' ').toUpperCase()+' · '+circuit.state.wiring+' wiring · '+state.stages.length+' stages · '+guide.connections.length+' electrical connections · '+circuit.components.filter(p=>p.type==='dpdt').length+' push/pull switches'));
   root.append(button('Start Guided Build',()=>{state.route='choosing';render(true);}));
  }else if(state.route==='choosing'){title.textContent='Choose your workbench route';root.append(title,button('Building from scratch',()=>{onStart();act('route','scratch');}),button('Installing an Apparition prewired kit',()=>{onStart();act('route','kit');}),button('Checking or modifying existing wiring',()=>{onStart();act('route','check');}),node('p','All routes use the same authoritative circuit. Kit steps are omitted only with verified supplied-assembly evidence. Checklist marks are your notes, not electrical test results.'));
  }else if(state.finished){title.textContent='Build complete';root.append(title,node('p','Your connection checklist is complete. These marks record your inspection; Apparition has not measured your guitar.'),button('Review connections',()=>{checklist=true;render();}),button('Return to first stage',()=>act('jump','@prepare')),node('p','Use Save SVG or Print diagram above for the full circuit.'));
  }else{
   if(state.route==='kit')root.append(node('p',state.kitVerified?factory.length+' factory-complete connections omitted from customer soldering steps. Verify the supplied assembly before installation.':'No verified assembly mapping is available for this circuit. Follow the full scratch-build sequence; confirm your kit contents before soldering.'));
   root.append(node('p','Stage '+(state.stages.indexOf(currentStage)+1)+' of '+state.stages.length+' · '+currentStage.label));
   title.textContent=row?(state.route==='check'?'Check: ':'Connect: ')+row.fromLabel+' → '+row.toLabel:currentStage.label;root.append(title);
   if(row){root.append(node('p','Connection '+(currentStage.connections.indexOf(row)+1)+' of '+currentStage.connections.length));const dl=node('dl');for(const [name,value] of [['From',row.fromLabel],['To',row.toLabel]]){dl.append(node('dt',name),node('dd',value));}root.append(dl,node('p',state.route==='check'?'Compare these physical endpoints with your existing wiring. '+row.method:row.method),node('p',row.kind.includes('pickup')||row.kind==='local-series'?'Verify conductor identity; insulate exposed series joints.':'Avoid stray strands and unintended terminal-to-casing bridges.'));if(state.skipped.includes(row.id))root.append(node('p','Skipped for now · review this connection before completion.'));}
   else if(state.current==='@prepare')root.append(node('p',state.route==='check'?'Compare the hardware and conductor functions with the circuit before modifying any wiring.':'Lay out the parts as shown. Identify pickup functions and switch commons before soldering. Avoid overheating terminals.'),node('p','The diagram is a solder-side guide. Verify orientation and terminal functions on your actual components.'));
   else {const ul=node('ul');for(const text of ['All required connections checked; resolve skipped or incomplete connections.','Inspect exposed conductor and stray strands. Check expected ground continuity.','Operate the selector through its positions. Confirm jack tip is signal and sleeve is ground.',...(circuit.components.some(p=>p.type==='dpdt')?['Check each push/pull in both positions against the full diagram.']:[]),'Compare the full diagram before connecting to an amplifier.'])ul.append(node('li',text));root.append(ul);const unresolved=required.filter(r=>!state.completed.includes(r.id));if(unresolved.length){root.append(node('p',unresolved.length+' connections remain unchecked.'));root.append(button('Review next unresolved connection',()=>act('jump',unresolved[0].id)));}}
   const controls=node('div');controls.className='guided-controls';const prev=button('Previous',()=>act('previous'));prev.disabled=state.current==='@prepare';const next=button(state.current==='@final'?'Confirm inspection / Build complete':state.route==='check'?'Checked / Next':'Done / Next',()=>act('done'));next.disabled=state.current==='@final'&&state.completed.length!==required.length;controls.append(prev,next);if(row)controls.append(button('Skip for now',()=>act('skip')));root.append(controls);
   const label=node('label','Return to a stage'),select=node('select');select.setAttribute('aria-label','Return to a stage');for(const stage of state.stages.filter(s=>!s.connections.length||s.connections.some(r=>!factory.includes(r.id)))){const o=node('option',stage.label);o.value=state.checkpoints.find(c=>c.stage===stage.id&&!factory.includes(c.id)).id;select.append(o);}select.value=state.checkpoints.find(c=>c.stage===currentStage.id&&!factory.includes(c.id)).id;select.addEventListener('change',()=>act('jump',select.value));label.append(select);root.append(label);
   const diagram=node('a','View highlighted connection on the diagram ↓');diagram.href='#generator-viewport';diagram.className='guided-diagram-link';root.append(diagram);
   root.append(button('Pause / view full diagram',()=>{state.route=null;save();render(true);}));
  }
  root.append(button(checklist?'Hide full connection checklist':'View full connection checklist',()=>{checklist=!checklist;render();}));
  const list=node('div');list.id='build-guide-steps';list.hidden=!checklist;
  if(checklist)for(const stage of state.stages.filter(s=>s.connections.some(r=>!factory.includes(r.id)))){const section=node('section');section.append(node('h4',stage.label));for(const connection of stage.connections.filter(r=>!factory.includes(r.id))){const item=node('div');item.className='build-step';const label=node('label'),box=node('input');box.type='checkbox';box.checked=state.completed.includes(connection.id);box.setAttribute('aria-label','Mark connection complete: '+connection.fromLabel+' to '+connection.toLabel);box.addEventListener('change',()=>act('toggle',connection.id));label.append(box,node('span',state.skipped.includes(connection.id)?'Skipped':box.checked?'Checked':'Unchecked'));item.append(label,button(connection.fromLabel+' → '+connection.toLabel,()=>{if(!['scratch','kit','check'].includes(state.route)){state.route='check';onStart();}act('jump',connection.id);}));section.append(item);}list.append(section);}root.append(list);
  root.append(node('small',storageOK?'Progress is saved on this device for this exact wiring and component specification.':'Device storage is unavailable; progress is retained for this session.'));
  highlightCheckpoint(mount,['scratch','kit','check'].includes(state.route)&&!state.finished?row:null);if(focus)title.focus({preventScroll:true});
 }
 return {update(c,g){circuit=c;guide=g;const identity=buildIdentity(c);if(state?.identity!==identity){let saved=null;try{saved=JSON.parse(storage.getItem(progressKey(identity)));}catch{storageOK=false;}state=createBuildProgress(c,g,saved,assembly);}render();},repaint(){if(state)highlightCheckpoint(mount,['scratch','kit','check'].includes(state.route)&&!state.finished?guide.connections.find(r=>r.id===state.current):null);},getState:()=>state};
}
